import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

/**
 * Semeia o formulário oficial da CEMIG nas concessionárias — bucket
 * `concessionaire-templates`, em todos os tenants que tenham a CEMIG.
 *
 * Mesmo molde do `seed-enel-forms`, inclusive a checagem de "já existe": o
 * `search` do storage casa pelo COMEÇO do nome e os arquivos são gravados
 * `{carimbo}_{nome}`, então a pasta é listada e filtrada pelo FINAL do nome.
 * Sem isso a função reenvia tudo a cada chamada (aconteceu na primeira versão
 * da rotina da ENEL).
 *
 * ATENÇÃO: este formulário AINDA NÃO tem mapa de preenchimento. Ele é semeado
 * para ficar disponível para download; ao tentar gerar, a tela avisa que falta
 * o mapa — que é o comportamento correto, e melhor do que devolver um arquivo
 * preenchido nos lugares errados.
 *
 * Original versionado em `docs/modelos-cemig/`.
 * Regerar o base64: `node scripts/build-seed-cemig-forms.cjs`.
 */

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const BUCKET = 'concessionaire-templates';
const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

const FORMULARIO_B64 = '';

const TEMPLATES: { fileName: string; mime: string; base64: string }[] = [
  { fileName: 'FORMULARIO_MICROGD_CEMIG_Rev_N4.xlsx', mime: XLSX_MIME, base64: FORMULARIO_B64 },
];

function bytesFromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  const json = (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

  try {
    const body = req.method === 'POST' ? await req.json().catch(() => ({})) : {};
    const overwrite = body?.overwrite === true;

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
    );

    const { data: concessionaires, error } = await supabase
      .from('energy_concessionaires')
      .select('id, name');
    if (error) return json({ ok: false, error: error.message }, 500);

    const alvos = (concessionaires ?? []).filter((c: { name: string }) => /cemig/i.test(c.name));
    const results: unknown[] = [];

    for (const c of alvos as { id: string; name: string }[]) {
      const { data: naPasta } = await supabase.storage.from(BUCKET).list(c.id, { limit: 1000 });
      const arquivos = (naPasta ?? []) as { name: string }[];

      for (const tpl of TEMPLATES) {
        const already = arquivos.find((f) => f.name.endsWith(tpl.fileName));
        if (already && !overwrite) {
          results.push({ concessionaria: c.id, arquivo: tpl.fileName, status: 'ja_existia' });
          continue;
        }
        const fileName = already && overwrite ? already.name : `${Date.now()}_${tpl.fileName}`;
        const { error: upErr } = await supabase.storage
          .from(BUCKET)
          .upload(`${c.id}/${fileName}`, bytesFromBase64(tpl.base64), {
            contentType: tpl.mime, upsert: true,
          });
        results.push(upErr
          ? { concessionaria: c.id, arquivo: tpl.fileName, status: 'erro', error: upErr.message }
          : { concessionaria: c.id, arquivo: fileName, status: 'enviado' });
      }
    }

    const enviados = results.filter((r) => (r as { status: string }).status === 'enviado').length;
    const erros = results.filter((r) => (r as { status: string }).status === 'erro').length;
    return json({ ok: erros === 0, concessionarias: alvos.length, enviados, erros, results });
  } catch (e) {
    return json({ ok: false, error: e instanceof Error ? e.message : 'erro inesperado' }, 500);
  }
});
